def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the color marking a diagonal with constant (column-row) modulo 3.
    colors = {v for row in grid for v in row if v}
    best = None
    for color in colors:
        counts = [0, 0, 0]
        for r in range(h):
            for c in range(w):
                if grid[r][c] == color:
                    counts[(c-r) % 3] += 1
        residue = max(range(3), key=lambda k: counts[k])
        score = counts[residue]
        if best is None or score > best[0]:
            best = (score, color, residue)
    _, guide, residue = best
    other = next(v for v in colors if v != guide)
    return [[guide if (c-r) % 3 == residue else other
             for c in range(w)] for r in range(h)]
